class Solution {
public:
    int sumDistance(vector<int>& nums, string s, int d) {
        const int MOD = 1e9 + 7;
        int n = nums.size();
        vector<long long> pos(n);
        for (int i = 0; i < n; ++i) {
            long long delta = (s[i] == 'R') ? d : -d;
            pos[i] = nums[i] + delta;
        }
        sort(pos.begin(), pos.end());
        long long total = 0;
        for (int i = 0; i < n; ++i) {
            long long count = 2LL * i - n + 1;
            long long term = (pos[i] % MOD) * (count % MOD) % MOD;
            total = (total + term) % MOD;
        }
        return (total % MOD + MOD) % MOD;
    }
};

import java.util.Arrays;

class Solution {
    public int sumDistance(int[] nums, String s, int d) {
        final int MOD = 1_000_000_007;
        int n = nums.length;
        long[] pos = new long[n];
        for (int i = 0; i < n; i++) {
            long delta = s.charAt(i) == 'R' ? d : -d;
            pos[i] = nums[i] + delta;
        }
        Arrays.sort(pos);
        long total = 0;
        for (int i = 0; i < n; i++) {
            long count = 2L * i - n + 1;
            long term = (pos[i] % MOD) * (count % MOD) % MOD;
            total = (total + term) % MOD;
        }
        return (int) ((total % MOD + MOD) % MOD);
    }
}

