    for (let i = 0; i < n; i++) {
        const delta = s[i] === 'R' ? bigD : -bigD;
        pos.push(BigInt(nums[i]) + delta);
    }
    pos.sort((a, b) => (a < b ? -1 : 1));
    let total = 0n;
    const bigN = BigInt(n);
    for (let i = 0; i < n; i++) {
        const count = 2n * BigInt(i) - bigN + 1n;
        const term = (pos[i] % MOD) * (count % MOD) % MOD;
        total = (total + term) % MOD;
    }
    return Number((total % MOD + MOD) % MOD);
